namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly object _lock = new();

    /// <summary>
    /// Returns the initial batch of notifications (called during SSR).
    /// </summary>
    public List<Notification> GetInitialNotifications()
    {
        lock (_lock)
        {
            var now = DateTime.UtcNow;
            var list = new List<Notification>
            {
                new(_nextId++, "Welcome to the notification centre!", now.AddMinutes(-10)),
                new(_nextId++, "Your profile was updated successfully.", now.AddMinutes(-5)),
                new(_nextId++, "New comment on your post.", now.AddMinutes(-2)),
            };
            return list;
        }
    }

    /// <summary>
    /// Simulates checking for new notifications.
    /// Randomly returns 0-1 new notifications per call.
    /// </summary>
    public List<Notification> CheckForNewNotifications()
    {
        lock (_lock)
        {
            if (Random.Shared.Next(3) == 0) // ~33% chance each poll
            {
                return [];
            }

            var messages = new[]
            {
                "Someone liked your post.",
                "You have a new follower!",
                "Scheduled maintenance tonight at 11 PM.",
                "Your export is ready to download.",
                "New reply in the discussion thread.",
                "Security alert: new sign-in detected.",
            };

            var msg = messages[Random.Shared.Next(messages.Length)];
            return [new Notification(_nextId++, msg, DateTime.UtcNow)];
        }
    }
}

