@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationSvc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;

    // Runs during SSR *and* on interactive init — but we gate the fetch
    // so we only load once (during SSR).  The interactive init reuses the
    // already-persisted component state, so _notifications is already populated.
    protected override void OnInitialized()
    {
        // During prerender the list is empty, so load initial data.
        // When the circuit starts the framework restores the rendered DOM,
        // and OnInitialized runs again — but we skip the fetch because
        // _notifications was already populated by the prerender pass.
        if (_notifications.Count == 0)
        {
            _notifications = NotificationSvc.GetInitialNotifications();
        }
    }

    // Only fires in the browser (never during static SSR), so this is
    // the safe place to kick off the background polling loop.
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }

        await base.OnAfterRenderAsync(firstRender);
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                var newItems = NotificationSvc.CheckForNewNotifications();
                if (newItems.Count > 0)
                {
                    _notifications.InsertRange(0, newItems);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (TaskCanceledException)
            {
                // Expected on dispose — exit cleanly.
                break;
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

